constexpr std::optional<VoiceId> mapGmMidiNoteToVoice(int midiNote) noexcept
{
    switch (midiNote)
    {
        case 35:
        case 36:
            return VoiceId::BassDrum;
        case 38:
        case 40:
            return VoiceId::SnareDrum;
        case 42:
        case 44:
        case 46:
            return VoiceId::HighHat;
        case 49:
        case 51:
        case 57:
            return VoiceId::Cymbal;
        case 54:
            return VoiceId::Tambourine;
        case 41:
        case 45:
        case 64:
            return VoiceId::LowConga;
        case 48:
        case 50:
        case 62:
        case 63:
            return VoiceId::HighConga;
        case 60:
        case 61:
            return VoiceId::LowBongo;
        case 75:
            return VoiceId::Claves;
        case 37:
        case 76:
        case 77:
            return VoiceId::RimShot;
        case 56:
            return VoiceId::CowBell;
        default:
            return std::nullopt;
    }
}

